package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	fmt.Fscan(in, &s)

	found := false
	for i := 0; i < 5; i++ {
		var card string
		fmt.Fscan(in, &card)
		if card[0] == s[0] || card[1] == s[1] {
			found = true
		}
	}

	if found {
		fmt.Fprintln(out, "YES")
	} else {
		fmt.Fprintln(out, "NO")
	}
}

